// spec: Реклама — где показывается и где нет
// seed: tests/seed.user.spec.ts
import { test, expect } from '@playwright/test';
import path from 'node:path';
import { slide } from '../helpers/monitor';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

test.describe('Реклама — где показывается и где нет', () => {
  test('Баннер «פרסומת» на шагах подготовки и в сводке, клик ведёт в /products #840d8543 #a5b844f5 @iphone @data', async ({ page }) => {
    // 1. Navigate to /home?mock=calm
    await page.goto('/home?mock=calm');

    // 2. Tap the button containing "התחלת ניטור"
    await page.getByRole('button', { name: 'התחלת ניטור' }).click();

    // 3. Step 1 "בדיקת בטיחות": banner visible, sound test, continue
    await expect(page.getByRole('heading', { name: 'בדיקת בטיחות' })).toBeVisible();
    await expect(page.getByRole('link', { name: /פרסומת/ })).toBeVisible();
    await page.getByRole('button', { name: /עוצמת צפצוף מקסימלית/ }).click();
    await page.getByRole('button', { name: 'השמעה' }).click();
    await page.getByRole('button', { name: 'שמעתי' }).click();
    const continueButton = page.getByRole('button', { name: 'המשך' });
    await expect(continueButton).toBeEnabled();
    await continueButton.click();

    // 4. Step 2 "כוונו את המצלמה לבריכה": banner visible, continue
    await expect(page.getByRole('heading', { name: 'כוונו את המצלמה לבריכה' })).toBeVisible();
    await expect(page.getByRole('link', { name: /פרסומת/ })).toBeVisible();
    await page.getByRole('button', { name: 'המשך' }).click();

    // 5. Step 3 "מי בבריכה היום?": banner visible and below "ילד חדש"
    await expect(page.getByRole('heading', { name: 'מי בבריכה היום?' })).toBeVisible();
    const banner = page.getByRole('link', { name: /פרסומת/ });
    await expect(banner).toBeVisible();
    const newChildBox = await page.getByRole('button', { name: 'ילד חדש' }).boundingBox();
    const bannerBox = await banner.boundingBox();
    expect(bannerBox!.y).toBeGreaterThan(newChildBox!.y);
    const startButton = page.getByRole('button', { name: 'התחלת ניטור' });
    await expect(startButton).toBeVisible();
    const selectAll = page.getByRole('button', { name: 'בחירת כולם' });
    if (await selectAll.isVisible()) {
      await selectAll.click();
    }
    await startButton.click();

    // 6. On /monitor/live end monitoring by dragging the slider knob from right to left
    await expect(page).toHaveURL(/\/monitor\/live/);
    await slide(page, 'כבה את המצלמה');

    // 7. Wait for /monitor/summary, expect banner, click it
    await page.waitForURL(/\/monitor\/summary/);
    const summaryBanner = page.getByRole('link', { name: /פרסומת/ });
    await expect(summaryBanner).toBeVisible();
    await summaryBanner.click();
    await page.waitForURL(/\/products/);
  });
});
